UPDATE menu_catalog SET data=json_set(data,'$.templates',json((SELECT json_group_array(json(CASE WHEN json_extract(value,'$.menu') LIKE 'DPA_MENU_V2:%' AND CASE WHEN json_valid(substr(json_extract(value,'$.menu'),13)) THEN json_extract(substr(json_extract(value,'$.menu'),13),'$.set.pricePerTable')=2000000 AND instr(lower(coalesce(json_extract(value,'$.name'),'')||coalesce(json_extract(substr(json_extract(value,'$.menu'),13),'$.set.name'),'')),'lẩu')>0 AND json_extract(substr(json_extract(value,'$.menu'),13),'$.set.people')=12 ELSE 0 END THEN json_set(value,'$.name','Lẩu 12 người – 2,000,000đ','$.menu','DPA_MENU_V2:'||json_set(substr(json_extract(value,'$.menu'),13),'$.set.name','Lẩu 12 người – 2,000,000đ','$.items',json('[{"name":"Gà","price":null,"quantity":1,"unit":"đĩa","included":true},{"name":"Chim","price":null,"quantity":1,"unit":"đĩa","included":true},{"name":"Bò hoa","price":null,"quantity":1,"unit":"đĩa","included":true},{"name":"Tôm","price":null,"quantity":1,"unit":"đĩa","included":true},{"name":"Mực","price":null,"quantity":1,"unit":"đĩa","included":true},{"name":"Diềm tim","price":null,"quantity":1,"unit":"đĩa","included":true}]'))) ELSE value END)) FROM json_each(data,'$.templates')))),version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='dpa-shared' AND EXISTS(SELECT 1 FROM json_each(data,'$.templates') WHERE json_extract(value,'$.menu') LIKE 'DPA_MENU_V2:%' AND CASE WHEN json_valid(substr(json_extract(value,'$.menu'),13)) THEN json_extract(substr(json_extract(value,'$.menu'),13),'$.set.pricePerTable')=2000000 AND instr(lower(coalesce(json_extract(value,'$.name'),'')||coalesce(json_extract(substr(json_extract(value,'$.menu'),13),'$.set.name'),'')),'lẩu')>0 AND json_extract(substr(json_extract(value,'$.menu'),13),'$.set.people')=12 ELSE 0 END);
